#pragma once
#include "SolverStatus.hpp"
#include "../assembly/MatrixAssembler.hpp"
#include "../results/AnalysisResults.hpp"
#include <Eigen/SparseCholesky>
#include <map>
#include <cmath>
namespace kopruq {
struct NodalLoad{Id node{};Eigen::Matrix<Real,6,1> values=Eigen::Matrix<Real,6,1>::Zero();};
struct StaticSolution{SolverStatus status;Eigen::VectorXd global,free,reactions;std::vector<Real> fixed;std::size_t total_dofs{},free_dofs{},fixed_dofs{};Real residual_norm{},relative_residual{};AnalysisResults results;};
class LinearStaticSolver{public:
static Eigen::SparseMatrix<Real> reduceKff(const Eigen::SparseMatrix<Real>&K,const std::vector<std::size_t>&f){std::vector<int>mp((size_t)K.rows(),-1);for(size_t i=0;i<f.size();++i)mp[f[i]]=(int)i;std::vector<Eigen::Triplet<Real>>t;for(int c=0;c<K.outerSize();++c)for(Eigen::SparseMatrix<Real>::InnerIterator it(K,c);it;++it)if(mp[it.row()]>=0&&mp[it.col()]>=0)t.emplace_back(mp[it.row()],mp[it.col()],it.value());Eigen::SparseMatrix<Real>o((int)f.size(),(int)f.size());o.setFromTriplets(t.begin(),t.end());return o;}
static Eigen::VectorXd assembleLoads(const DofManager&d,const std::vector<NodalLoad>&ls){Eigen::VectorXd f=Eigen::VectorXd::Zero((Eigen::Index)d.dof_count());for(const auto&l:ls){if(!l.values.allFinite())throw AssemblyError(AssemblyErrorCode::MissingNode,"nodal load is non-finite");auto a=d.node_dofs(l.node);for(int i=0;i<6;++i)f((Eigen::Index)a[i])+=l.values(i);}return f;}
static AnalysisResults recover(const Model&m,const std::map<Id,std::array<bool,6>>&rs,const std::vector<NodalLoad>&ls,const Eigen::VectorXd&U){DofManager dm(m);auto F=assembleLoads(dm,ls);auto K=MatrixAssembler::assemble(m);Eigen::VectorXd q=K*U-F;AnalysisResults o;for(const auto&n:m.nodes){NodeResults z;z.node_id=n.id;auto d=dm.node_dofs(n.id);auto it=rs.find(n.id);z.restrained=it!=rs.end()?it->second:std::array<bool,6>{};for(int i=0;i<6;++i){z.displacement[i]=U((Eigen::Index)d[i]);z.reaction[i]=z.restrained[i]?q((Eigen::Index)d[i]):0;}o.nodes.push_back(z);}std::map<Id,const Material*>ma;for(const auto&x:m.materials)ma[x.id]=&x;std::map<Id,const Section*>se;for(const auto&x:m.sections)se[x.id]=&x;for(const auto&e:m.beams){const Node*a=nullptr,*b=nullptr;for(const auto&n:m.nodes){if(n.id==e.node1)a=&n;if(n.id==e.node2)b=&n;}auto&p=*ma[e.material];auto&s=*se[e.section];Beam3DGeometry g{{a->x,a->y,a->z},{b->x,b->y,b->z},e.reference_y};Beam3DProperties bp{p.elastic_modulus,p.elastic_modulus/(2*(1+p.poisson_ratio)),s.area,s.Iy,s.Iz,s.J};auto T=Beam3D::transformation(Beam3D::axes(g));auto kl=Beam3D::localStiffness((g.node2-g.node1).norm(),bp);auto d=dm.element_dofs(e.node1,e.node2);Eigen::Matrix<Real,12,1>u,fl,fg;for(int i=0;i<12;++i)u(i)=U((Eigen::Index)d[i]);fl=kl*T*u;fg=T.transpose()*fl;ElementResults er;er.element_id=e.id;for(int i=0;i<12;++i){er.local_end_force[i]=fl(i);er.global_end_force[i]=fg(i);}Eigen::Vector3d f1=fg.template head<3>(),f2=fg.template segment<3>(6),m1=fg.template segment<3>(3),m2=fg.template segment<3>(9),r=(g.node2-g.node1).eval();er.force_balance=f1+f2;er.moment_balance=m1+m2+r.cross(f2);er.force_balance_norm=er.force_balance.norm();er.moment_balance_norm=er.moment_balance.norm();Real fs=f1.norm()+f2.norm(),ms=m1.norm()+m2.norm()+r.norm()*(f1.norm()+f2.norm());er.normalized_force_error=fs>0?er.force_balance_norm/fs:0;er.normalized_moment_error=ms>0?er.moment_balance_norm/ms:0;if(o.elements.empty()||er.normalized_force_error>o.max_element_force_error){o.max_element_force_error=er.normalized_force_error;o.max_force_element_id=e.id;}if(o.elements.empty()||er.normalized_moment_error>o.max_element_moment_error){o.max_element_moment_error=er.normalized_moment_error;o.max_moment_element_id=e.id;}o.elements.push_back(er);}Eigen::Vector3d af=Eigen::Vector3d::Zero(),ar=Eigen::Vector3d::Zero(),am=Eigen::Vector3d::Zero(),arm=Eigen::Vector3d::Zero();for(const auto&l:ls){const Node*n=nullptr;for(const auto&x:m.nodes)if(x.id==l.node)n=&x;Eigen::Vector3d r(n->x,n->y,n->z),f=l.values.head<3>(),mm=l.values.tail<3>();af+=f;am+=mm+r.cross(f);}for(const auto&n:o.nodes){const Node*x=nullptr;for(const auto&y:m.nodes)if(y.id==n.node_id)x=&y;Eigen::Vector3d r(x->x,x->y,x->z),f(n.reaction[0],n.reaction[1],n.reaction[2]),mm(n.reaction[3],n.reaction[4],n.reaction[5]);ar+=f;arm+=mm+r.cross(f);}o.force_balance=af+ar;o.moment_balance=am+arm;o.force_balance_norm=o.force_balance.norm();o.moment_balance_norm=o.moment_balance.norm();o.force_equilibrium_error=o.force_balance_norm/(af.norm()+ar.norm()>0?af.norm()+ar.norm():1);o.moment_equilibrium_error=o.moment_balance_norm/(am.norm()+arm.norm()>0?am.norm()+arm.norm():1);o.valid=true;return o;}
static StaticSolution solve(const Model&m,const std::map<Id,std::array<bool,6>>&rs,const std::vector<NodalLoad>&ls){StaticSolution o;try{DofManager dm(m);o.total_dofs=dm.dof_count();if(rs.empty()){o.status={false,"no restraints",SolverStatusCode::NoRestraints};return o;}auto all=rs;for(const auto&n:m.nodes)if(!all.count(n.id))all[n.id]={};auto b=MatrixAssembler::classify(dm,all);o.free_dofs=b.free.size();o.fixed_dofs=b.fixed.size();Eigen::VectorXd F=assembleLoads(dm,ls);Eigen::SparseMatrix<Real>K=MatrixAssembler::assemble(m);Eigen::SparseMatrix<Real>Kff=reduceKff(K,b.free);Eigen::VectorXd Ff((Eigen::Index)b.free.size());for(size_t i=0;i<b.free.size();++i)Ff((Eigen::Index)i)=F((Eigen::Index)b.free[i]);Eigen::SimplicialLDLT<Eigen::SparseMatrix<Real>>fac;fac.compute(Kff);if(fac.info()!=Eigen::Success){o.status={false,"singular system",SolverStatusCode::SingularSystem};return o;}o.free=fac.solve(Ff);o.global=Eigen::VectorXd::Zero((Eigen::Index)dm.dof_count());for(size_t i=0;i<b.free.size();++i)o.global((Eigen::Index)b.free[i])=o.free((Eigen::Index)i);o.results=recover(m,all,ls,o.global);o.reactions=Eigen::VectorXd::Zero((Eigen::Index)dm.dof_count());for(const auto&n:o.results.nodes){auto d=dm.node_dofs(n.node_id);for(int i=0;i<6;++i)o.reactions((Eigen::Index)d[i])=n.reaction[i];}o.status={true,"linear static solution and recovery completed",SolverStatusCode::Success};}catch(const std::exception&e){o.status={false,e.what(),SolverStatusCode::InvalidModel};}return o;}
};}






